<?php
$page_title = 'Dashboard'; require_once __DIR__ . '/header.php';
$today = db()->query("SELECT COUNT(*) AS cnt, COALESCE(SUM(amount),0) AS total FROM payments WHERE DATE(payment_datetime) = CURDATE()")->fetch();
$month = db()->query("SELECT COUNT(*) AS cnt, COALESCE(SUM(amount),0) AS total FROM payments WHERE YEAR(payment_datetime)=YEAR(CURDATE()) AND MONTH(payment_datetime)=MONTH(CURDATE())")->fetch();
$recent = db()->query('SELECT p.*, s.service_item FROM payments p LEFT JOIN services s ON p.service_id=s.id ORDER BY p.payment_datetime DESC LIMIT 7')->fetchAll();
?>
<div class="welcome"><div><span>OVERVIEW</span><h2>Welcome back, <?= e(explode(' ', $_SESSION['user']['full_name'])[0]) ?>!</h2><p>Keep track of completed-service payments with ease.</p></div><a class="primary" href="payment.php">＋ Record New Payment</a></div>
<div class="stats"><article><span class="stat-icon teal">₱</span><div><small>Today's Collection</small><strong><?= peso((float)$today['total']) ?></strong><em><?= $today['cnt'] ?> payment<?= $today['cnt'] != 1 ? 's' : '' ?> recorded</em></div></article><article><span class="stat-icon blue">▤</span><div><small>Payments Today</small><strong><?= $today['cnt'] ?></strong><em>Completed services</em></div></article><article><span class="stat-icon violet">◷</span><div><small>This Month</small><strong><?= peso((float)$month['total']) ?></strong><em><?= $month['cnt'] ?> payments recorded</em></div></article></div>
<div class="panel"><div class="panel-head"><div><h3>Recent Payments</h3><p>The latest completed-service payments</p></div><a href="records.php">View all →</a></div><?php if(!$recent): ?><div class="empty">No payments recorded yet. <a href="payment.php">Record your first payment.</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Patient / Client</th><th>Service</th><th>Amount</th><th>Date & Time</th><th>Recorded By</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><strong><?= e($r['patient_name']) ?></strong></td><td><?= e($r['service_item'] ?: $r['service_name']) ?></td><td class="amount"><?= peso((float)$r['amount']) ?></td><td><?= date('M j, Y · g:i A', strtotime($r['payment_datetime'])) ?></td><td><?= e($r['recorded_by_name']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
